CONFIG_DIFF_MAX_INPUT_BYTES = 1024 * 1024


def _json_pointer_token(token):
    """RFC6901 reference token 转义：~ 编码为 ~0，/ 编码为 ~1。"""
    return token.replace("~", "~0").replace("/", "~1")


def _diff_collect(old, new, path, changes):
    """按键序无关契约收集 OLD、NEW 的差异项到 changes。

    对象递归，键按 Unicode 码点升序深度优先；数组整体比较且顺序敏感，
    整组不同仅出一项；标量按 JSON 类型与值比较。path 为 RFC6901 JSON
    Pointer（根为 ""）。仅不同的数组或标量（及缺失对象键）生成项。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        for key in sorted(set(old) | set(new)):
            child = path + "/" + _json_pointer_token(key)
            if key in old and key in new:
                _diff_collect(old[key], new[key], child, changes)
            elif key in old:
                # 仅旧侧存在；合法 port-security 配置各层键集固定，不会到达
                changes.append(
                    {"path": child, "before": _canonical(old[key]),
                     "after": None}
                )
            else:
                changes.append(
                    {"path": child, "before": None,
                     "after": _canonical(new[key])}
                )
        return
    # 两数组整体（顺序敏感）、两标量（JSON 类型+值）或类别不一致：
    # 不同即整值一项，前后值按同一规则规范化
    if not _json_equal(old, new):
        changes.append(
            {"path": path, "before": _canonical(old),
             "after": _canonical(new)}
        )


def _diff_size(value):
    """工作量公式的 S：标量 1；数组 1+各元素 S 之和；
    对象 1+键数+各值 S 之和。"""
    if isinstance(value, dict):
        return 1 + len(value) + sum(_diff_size(item) for item in value.values())
    if isinstance(value, list):
        return 1 + sum(_diff_size(item) for item in value)
    return 1


def _diff_size_charge(value, remaining):
    """S 的计费版：从剩余额度扣减 S(value)，返回扣后额度（耗尽为 0）。

    对象先计 1+键数，再按键的 Unicode 码点升序逐值计费；数组先计 1，
    再按元素序逐项计费；标量计 1。累计首次超过剩余额度即抛
    DiffWorkLimit，不再访问后续元素或键值；额度足够时累计恰为
    S(value)，与 _diff_size 一致。
    """
    if isinstance(value, dict):
        cost = 1 + len(value)
        if cost > remaining:
            raise DiffWorkLimit
        remaining -= cost
        for key in sorted(value):
            remaining = _diff_size_charge(value[key], remaining)
        return remaining
    if isinstance(value, list):
        if remaining < 1:
            raise DiffWorkLimit
        remaining -= 1
        for item in value:
            remaining = _diff_size_charge(item, remaining)
        return remaining
    if remaining < 1:
        raise DiffWorkLimit
    return remaining - 1


def _diff_work(old, new, remaining):
    """按工作量公式无副作用预演 D，返回剩余额度（耗尽为 0）。

    两值均为对象时计 1+并集键数，共有键递归计 D，单侧键计该侧 S；
    其余（含数组整体）计 1+S(旧值)+S(新值)。键按 Unicode 码点升序
    累计，递归逐层传递剩余额度；等于上限合法，首次超过即抛
    DiffWorkLimit，此后不再访问后续元素、键值或单侧子树。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        cost = 1 + len(set(old) | set(new))
        if cost > remaining:
            raise DiffWorkLimit
        remaining -= cost
        for key in sorted(set(old) | set(new)):
            if key in old and key in new:
                remaining = _diff_work(old[key], new[key], remaining)
            else:
                remaining = _diff_size_charge(
                    old[key] if key in old else new[key], remaining
                )
        return remaining
    if remaining < 1:
        raise DiffWorkLimit
    remaining -= 1
    remaining = _diff_size_charge(old, remaining)
    return _diff_size_charge(new, remaining)


def _cmd_config_diff(
    old_path,
    new_path,
    max_diff_work=DEFAULT_MAX_DIFF_WORK,
    max_input_bytes=CONFIG_DIFF_MAX_INPUT_BYTES,
    max_output_bytes=None,
):
    if max_output_bytes is None:
        # 调用时解析缺省：测试可在导入后补丁 DEFAULT_MAX_OUTPUT_BYTES
        max_output_bytes = DEFAULT_MAX_OUTPUT_BYTES
    try:
        # 先打开两文件，任一失败即停；均可读后按 OLD、NEW 顺序分块读
        with open(old_path, "rb") as old_handle, open(
            new_path, "rb"
        ) as new_handle:
            old_raw = _read_limited(old_handle, max_input_bytes)
            if old_raw is None:
                _fail("input_limit")
                return 5
            new_raw = _read_limited(new_handle, max_input_bytes)
            if new_raw is None:
                _fail("input_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        old_config = parse_json(old_raw)
        new_config = parse_json(new_raw)
        # 两份均按既有 port-security 契约全量解析校验
        validate_security_config(old_config)
        validate_security_config(new_config)
        # 语义校验后先无副作用预演根值 D；首次超过即停止，不生成差异
        _diff_work(old_config, new_config, max_diff_work)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except DiffWorkLimit:
        _fail("diff_work_limit")
        return 5
    changes = []
    _diff_collect(old_config, new_config, "", changes)
    result = {"equal": not changes, "changes": changes}
    payload = _result_bytes(result)
    # 输出字节上界（含末尾 LF）写出前判定；等于上限合法，超限时 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


def _cmd_config_export(
    config_path,
    max_export_work=DEFAULT_MAX_EXPORT_WORK,
    max_input_bytes=CONFIG_DIFF_MAX_INPUT_BYTES,
    max_output_bytes=None,
):
    if max_output_bytes is None:
        # 调用时解析缺省：测试可在导入后补丁 DEFAULT_MAX_OUTPUT_BYTES
        max_output_bytes = DEFAULT_MAX_OUTPUT_BYTES
    try:
        with open(config_path, "rb") as config_handle:
            # 仅读取一个 CONFIG；分块读取与字节边界沿用 config-diff
            config_raw = _read_limited(config_handle, max_input_bytes)
            if config_raw is None:
                _fail("input_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        config = parse_json(config_raw)
        # 按既有 port-security 契约全量解析校验（编码、JSON、语义）
        validate_security_config(config)
        # 语义校验后先无副作用预演根值 S；等于上限合法，首次超过即停止，
        # 不构造导出文档。S 与遍历次序（对象键按 Unicode 码点升序）沿用
        # config-diff 的 _diff_size_charge
        _diff_size_charge(config, max_export_work)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except DiffWorkLimit:
        _fail("export_work_limit")
        return 5
    canonical = _canonical(config)
    # config 单独按紧凑 UTF-8 口径编码并加 LF 后的 SHA-256 小写十六进制
    config_payload = _result_bytes(canonical)
    digest = hashlib.sha256(config_payload).hexdigest()
    result = {"schema": 1, "config": canonical, "sha256": digest}
    payload = _result_bytes(result)
    # 输出字节上界（含末尾 LF）写出前判定；等于上限合法，超限时 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


